<?php require __DIR__.'/_layout.php';x1_require_role('admin');$db=x1_db();if($_SERVER['REQUEST_METHOD']==='POST'){x1_check_csrf();if($db){$act=(string)($_POST['act']??'add');if($act==='add'){x1_db_exec('INSERT INTO maintenance_windows(id,enabled,starts_at,ends_at,message,created_by,created_at) VALUES(?,?,?,?,?,?,?)',[x1_id(),1,(string)$_POST['starts_at'],trim((string)$_POST['ends_at'])?:null,trim((string)$_POST['message']),(string)($_SESSION['admin']??''),date('c')]);x1_audit('maintenance_add',(string)$_POST['starts_at']);}else{x1_db_exec('UPDATE maintenance_windows SET enabled=CASE enabled WHEN 1 THEN 0 ELSE 1 END WHERE id=?',[(string)$_POST['id']]);x1_audit('maintenance_toggle',(string)$_POST['id']);}}header('Location:maintenance.php');exit;}$rows=$db?x1_db_all('SELECT * FROM maintenance_windows ORDER BY starts_at DESC'):[];$active=x1_maintenance_active();top(tr('Maintenance','Manutenção'));?><section class="card hero"><div class=eyebrow>MAINTENANCE SCHEDULER</div><h2><?=$active?tr('Maintenance is currently ACTIVE','Manutenção atualmente ATIVA'):tr('No active maintenance window','Sem janela de manutenção ativa')?></h2><?php if($active):?><p><?=h($active['message'])?></p><?php endif?></section><section class=section><form method=post><input type=hidden name=csrf value="<?=x1_csrf()?>"><input type=hidden name=act value=add><div class=formgrid><label><?=tr('Starts at','Começa')?><input name=starts_at value="<?=date('c')?>" required></label><label><?=tr('Ends at','Termina')?><input name=ends_at></label><label><?=tr('Message','Mensagem')?><textarea name=message></textarea></label></div><button><?=tr('Schedule','Agendar')?></button></form></section><section class=section><table><tr><th>Start</th><th>End</th><th>Message</th><th>Status</th><th></th></tr><?php foreach($rows as $x):?><tr><td><?=h($x['starts_at'])?></td><td><?=h($x['ends_at'])?></td><td><?=h($x['message'])?></td><td><?=$x['enabled']?'Enabled':'Disabled'?></td><td><form method=post><input type=hidden name=csrf value="<?=x1_csrf()?>"><input type=hidden name=act value=toggle><input type=hidden name=id value="<?=h($x['id'])?>"><button><?=tr('Toggle','Alternar')?></button></form></td></tr><?php endforeach?></table></section><?php bottom();